package com.stackgen.metadataservice.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="entity_relationships", indexes={@Index(name="idx_rel_project",columnList="project_id"),@Index(name="idx_rel_source",columnList="source_entity_id"),@Index(name="idx_rel_target",columnList="target_entity_id")})
public class EntityRelationship { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="project_id",nullable=false) private UUID projectId; @Column(name="source_entity_id",nullable=false) private UUID sourceEntityId; @Column(name="target_entity_id",nullable=false) private UUID targetEntityId; @Column(name="relationship_type",nullable=false,length=30) private String relationshipType; @Column(name="field_name",nullable=false,length=100) private String fieldName; @Column(name="join_column",length=100) private String joinColumn; @Column(name="mapped_by",length=100) private String mappedBy; @Column(name="is_owning_side",nullable=false) private boolean owningSide=true;
 public UUID getId(){return id;} public UUID getProjectId(){return projectId;} public void setProjectId(UUID v){projectId=v;} public UUID getSourceEntityId(){return sourceEntityId;} public void setSourceEntityId(UUID v){sourceEntityId=v;} public UUID getTargetEntityId(){return targetEntityId;} public void setTargetEntityId(UUID v){targetEntityId=v;} public String getRelationshipType(){return relationshipType;} public void setRelationshipType(String v){relationshipType=v;} public String getFieldName(){return fieldName;} public void setFieldName(String v){fieldName=v;} public String getJoinColumn(){return joinColumn;} public void setJoinColumn(String v){joinColumn=v;} public String getMappedBy(){return mappedBy;} public void setMappedBy(String v){mappedBy=v;} public boolean isOwningSide(){return owningSide;} public void setOwningSide(boolean v){owningSide=v;}
}
